[
  {
    "pd_decision_conflict": "Honestly, I wish this hadn't landed on me.",
    "sys_fairness_reciprocity": "She worked every hour I did",
    "ce_mental_state_attribution": "hate for her to walk away thinking her effort counted for less"
  },
  {
    "pd_decision_conflict": "keep turning it over and still can't give a clean answer tonight",
    "ae_welfare_concern": "I care that he isn't left out after all those late hours",
    "pda_self_consequence_regret": "I'd rather wait until I'm sure than say something I regret"
  },
  {
    "pd_decision_conflict": "Why me, though? That's the part that sits heavy.",
    "ae_welfare_concern": "the thought of her being passed over bothers me",
    "sys_fairness_reciprocity": "She stayed just as late"
  },
  {
    "sys_fairness_reciprocity": "We did the same work, side by side.",
    "ae_welfare_concern": "a careless answer could cost him"
  },
  {
    "sys_fairness_reciprocity": "She deserves not to be shortchanged",
    "ae_welfare_concern": "the idea of her getting less would stick with me",
    "pd_decision_conflict": "I just feel strange being the judge here"
  },
  {
    "sys_fairness_reciprocity": "We worked the same hours, and I'd hoped fairness would handle it",
    "ae_welfare_concern": "I do care what happens to him.",
    "pd_decision_conflict": "I just don't trust myself to decide someone else's pay on the spot"
  },
  {
    "sys_fairness_reciprocity": "nothing about her work was different from mine",
    "ae_welfare_concern": "I care that she's treated right.",
    "pd_decision_conflict": "What makes me hesitate is the weight of it."
  },
  {
    "ce_understood_harm": "saying no could quietly take something from him",
    "pd_decision_conflict": "saying yes feels like I'm acting as his boss",
    "ae_welfare_concern": "How he comes out of this matters to me"
  },
  {
    "sys_fairness_reciprocity": "Same work, same late night, same good outcome.",
    "ae_welfare_concern": "don't want her feeling overlooked or unpaid",
    "ce_mental_state_attribution": "don't want her feeling overlooked"
  },
  {
    "pd_decision_conflict": "part of me wishes I'd never been asked.",
    "sys_fairness_reciprocity": "He gave the same time I did",
    "ae_welfare_concern": "don't like picturing him going home with nothing to show for it"
  }
]
